// Ace must count as eleven before soft-hand adjustment.
function score(cards){let total=0,aces=0;cards.forEach(c=>{if(c.rank===1){total+=11;aces++;}else total+=Math.min(10,c.rank);});while(total>21&&aces>0){total-=10;aces--;}return total;}
function rouletteReturn(n,kind,choice,bet){let win=false,m=2;if(kind==='number'){win=n===choice;m=36;}else if(kind==='red')win=RED.includes(n);else if(kind==='black')win=n!==0&&!RED.includes(n);else if(kind==='even')win=n!==0&&n%2===0;else if(kind==='odd')win=n%2===1;return win?bet*m:0;}
function slotReturn(values,bet){if(values.every(x=>x===values[0]))return bet*10;if(new Set(values).size===2)return bet;return 0;}
function diceReturn(a,b,choice,bet){const sum=a+b;return ((choice==='low'&&sum<7)||(choice==='high'&&sum>7))?bet*2:choice==='seven'&&sum===7?bet*5:0;}
const fresh=()=>({balance:START,history:[],settings:{...DEFAULT},name:'Guest',favorites:[],started:Date.now(),ended:false,endedAt:null});
