 useEffect(()=>{scene.stopAnimation();if(!motionOK){scene.setValue(1);return;}scene.setValue(0);const a=Animated.timing(scene,{toValue:1,duration:230,useNativeDriver:Platform.OS!=='web'});a.start();return()=>a.stop();},[tab,game,motionOK,scene]);
 useEffect(()=>{const x=Math.max(0,['home','games','stats','settings'].indexOf(tab))*(navCell+3);navX.stopAnimation();if(!motionOK||!navWidth){navX.setValue(x);return;}const a=Animated.spring(navX,{toValue:x,damping:23,stiffness:240,mass:1,useNativeDriver:Platform.OS!=='web'});a.start();return()=>a.stop();},[tab,navCell,navWidth,motionOK,navX]);
 const rounds=data.history.length;const wins=data.history.filter(x=>x.net>0).length;const losses=data.history.filter(x=>x.net<0).length;const totalNet=data.history.reduce((v,x)=>v+x.net,0);const current=GAMES.find(g=>g.id===game);const elapsed=Math.max(0,Math.floor(((data.endedAt||now)-data.started)/60000));const timeCapped=s.maxMinutes>0&&elapsed>=s.maxMinutes;const capped=!!data.ended||(s.maxRounds>0&&rounds>=s.maxRounds)||timeCapped;const turnover=data.history.reduce((a,h)=>a+h.stake,0);const returned=data.history.reduce((a,h)=>a+h.payout,0);const balanceLabel=s.showBalance?fmt(data.balance,lang):'••••';
 useEffect(()=>{let active=true;AsyncStorage.getItem(KEY).then(raw=>{if(!active||!raw)return;try{const v=JSON.parse(raw);if(Number.isFinite(v.balance)&&v.balance>=0&&Array.isArray(v.history))setData({...fresh(),...v,name:typeof v.name==='string'?v.name.slice(0,28):'Guest',favorites:Array.isArray(v.favorites)?v.favorites.filter(id=>GAMES.some(g=>g.id===id)):[],settings:{...DEFAULT,...v.settings}});}catch{}}).catch(()=>{}).finally(()=>{if(active)setReady(true);});return()=>{active=false;};},[]);
 useEffect(()=>{if(ready)AsyncStorage.setItem(KEY,JSON.stringify(data)).catch(()=>setNotice(t('Не удалось сохранить данные','Could not save data')));},[data,ready]);
 useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>{clearInterval(id);clearTimeout(timer.current);};},[]);
 const setting=(k,v)=>setData(d=>({...d,settings:{...d.settings,[k]:v}}));
 function nav(v){if(busy||hand)return;setTab(v);setGame(null);setResult(null);setNotice('');}
 function openGame(id){if(busy||hand)return;setGame(id);setResult(null);setNotice('');setTab('games');}
 function favorite(id){setData(d=>({...d,favorites:d.favorites.includes(id)?d.favorites.filter(x=>x!==id):[...d.favorites,id]}));}
 function animate(){if(!motionOK){fade.setValue(1);return;}fade.setValue(.4);Animated.timing(fade,{toValue:1,duration:260,useNativeDriver:Platform.OS!=='web'}).start();}
 function finish(id,stake,payout,detail){const net=payout-stake;setData(d=>({...d,balance:d.balance+net,history:[{id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),game:id,stake,payout,net,detail,date:Date.now()},...d.history]}));setResult({net,payout,detail});setHand(null);setBusy(false);lock.current=false;animate();}
 function startRound(){if(!ready||lock.current||busy||hand||capped||Date.now()-data.started>=s.maxMinutes*60000&&s.maxMinutes>0||bet>data.balance||!Number.isInteger(bet)||bet<1)return;lock.current=true;setNotice('');setResult(null);setBusy(true);const b=bet;
  if(game==='blackjack'){const player=[draw(),draw()],dealer=[draw(),draw()];if(score(player)===21||score(dealer)===21){const p=score(player),d=score(dealer);finish(game,b,p===d?b:p===21?b+b*1.5:0,{player,dealer});}else{setHand({player,dealer,stake:b});setBusy(false);}return;}
  const go=()=>{if(game==='roulette'){const n=random(37);finish(game,b,rouletteReturn(n,rouletteKind,rouletteNum,b),{n,kind:rouletteKind,choice:rouletteNum});}else if(game==='slots'){const values=[random(5),random(5),random(5)];finish(game,b,slotReturn(values,b),{values});}else if(game==='dice'){const a=random(6)+1,bb=random(6)+1;finish(game,b,diceReturn(a,bb,diceChoice,b),{a,b:bb,choice:diceChoice});}else{setBusy(false);lock.current=false;}};
  if(motionOK)timer.current=setTimeout(go,450);else go();
 }
 function settleBlackjack(h){if(score(h.player)>21){finish('blackjack',h.stake,0,{player:h.player,dealer:h.dealer});return;}let dealer=[...h.dealer];while(score(dealer)<17)dealer.push(draw());const p=score(h.player),d=score(dealer);finish('blackjack',h.stake,d>21||p>d?h.stake*2:p===d?h.stake:0,{player:h.player,dealer});}
 function hit(){if(!hand)return;const h={...hand,player:[...hand.player,draw()]};if(score(h.player)>=21)settleBlackjack(h);else setHand(h);}
